"""Authored teaching scripts and deterministic scene instructions. No downloads."""
import json
from pathlib import Path

root=Path(__file__).resolve().parents[1]
lessons=[]
def stage(title,spoken,**visual):
    return dict(title=title,spoken=spoken,**visual)
def lesson(id,group,title,objective,sourceIds,stages,explore):
    assert len(stages)==4
    lessons.append(dict(id=id,group=group,title=title,objective=objective,sourceIds=sourceIds,stages=stages,explore=explore))
def twin(id,title,objective,parts):
    refs=['uiphemodynamics','esvs2022','keijsers2015']
    lesson(id,'twin',title,objective,refs,[stage(*p[:2],scenario=p[2],view=p[3],phase=p[4],shot=p[5]) for p in parts],f'/flebotwin?scenario={id}')

twin('TW01','La postura cambia el contexto','Relaciona altura, potencial y presión sin confundirlos con una medición clínica.',[
 ('Sitúa la red','En decúbito, el eje de esta red se aproxima a la horizontal. El azul representa la rama profunda y el violeta la superficial. Son cuatro compartimentos de un modelo docente; las separaciones y los colores permiten reconocer sus conexiones.','TW01','flow',[0,.2],'overview'),
 ('Presión y altura','Para interpretar el flujo debemos considerar tanto la presión como la altura. La curva muestra la presión distal calculada mientras actúa la bomba. La lectura cambia con el ciclo; una presión aislada no describe toda la dinámica de la red.','TW01','flow',[.2,.8],'deep'),
 ('Cambia una condición','Pasamos al perfil de bipedestación. La orientación y la carga gravitacional cambian; las unidades continúan siendo relativas. Mira la nueva curva y conserva la misma referencia antes de comparar. El resultado representa estas ecuaciones, no la presión de una persona.','TW02','flow',[0,1],'overview'),
 ('Comprueba la interpretación','Regresamos al decúbito. Identifica qué cambió con la postura y qué permanece: las conexiones y la activación de la bomba. Al explorar, modifica una sola condición cada vez y relaciona la escena con la curva correspondiente.','TW01','flow',[0,1],'overview')])
twin('TW02','Del decúbito a la bipedestación','Distingue orientación anatómica, gravedad y representación del circuito.',[
 ('Referencia vertical','Esta vista sitúa la red en bipedestación. Localiza los extremos proximal y distal antes de seguir las partículas. Su desplazamiento procede del flujo calculado; el giro del conjunto representa la postura y no una deformación del cuerpo.','TW02','flow',[0,.2],'overview'),
 ('Lee el circuito','El circuito permite reconocer los cuatro compartimentos sin transparencias. Cada nodo tiene presión y volumen; las conexiones muestran flujos con signo. Esta representación ayuda a comprobar lo que el dibujo tridimensional puede ocultar desde un ángulo concreto.','TW02','circuit',[0,1],'overview'),
 ('Contrasta la postura','Ahora se muestra el perfil en decúbito. La presión se interpreta con la misma convención del modelo. No traduzcas estas unidades a milímetros de mercurio ni uses el cambio de altura como una predicción individual.','TW01','flow',[0,1],'overview'),
 ('Vuelve al mecanismo','De nuevo en bipedestación, observa contracción y relajación. La gravedad modifica el contexto en el que trabaja la bomba, pero una animación por sí sola no determina síntomas ni competencia venosa en un paciente.','TW02','flow',[0,1],'deep')])
twin('TW03','La bomba muscular en acción','Relaciona contracción, desplazamiento y curva temporal del mismo cálculo.',[
 ('Antes de contraer','Localiza la rama profunda y la envoltura muscular ilustrativa. El modelo conserva sangre dentro de sus compartimentos. Las partículas son trazadores simbólicos: hacen visible el transporte sin representar la velocidad real de cada célula.','TW03','flow',[0,0],'overview'),
 ('Eyección','La activación de la bomba aumenta. Mira la envoltura y sigue el ascenso de la curva de flujo. El cursor señala el mismo instante que utiliza la escena. La contracción visual y la lectura numérica pertenecen a una única solución.','TW03','flow',[0,.25],'deep'),
 ('Relajación y relleno','Al disminuir la activación, cambian las presiones y los flujos entre compartimentos. Observa la conexión entre los sistemas y evita asumir que todas las ramas se mueven siempre en el mismo sentido. La dirección está determinada por este cálculo.','TW03','flow',[.25,.8],'superficial'),
 ('Ciclo completo','Revisamos un ciclo completo. Compara amplitud y forma de la onda, y después prueba una activación menor en Explorar. La contracción y las valvas son esquemas docentes; esta pieza no reproduce una biomecánica individual validada.','TW03','flow',[0,1],'overview')])
twin('TW04','Qué cambia al reducir la bomba','Compara perfiles manteniendo explícita la condición que cambia.',[
 ('Activación menor','El perfil utiliza una activación muscular reducida. Reconoce primero la misma red y las mismas conexiones. El propósito de la comparación es observar cómo cambian las ondas cuando modificamos una condición del modelo.','TW04','flow',[0,.2],'overview'),
 ('Observa la onda','Sigue un ciclo de este perfil. La amplitud y la distribución temporal del flujo deben leerse en la curva, junto al movimiento. Una imagen detenida de un vaso no permite deducir la eficacia funcional de la bomba de una persona.','TW04','flow',[0,1],'deep'),
 ('Perfil de contraste','Mostramos ahora la bomba más activa. La curva y la escena se reconstruyen con las condiciones de este segundo perfil. Compara sus formas; no interpretes el retorno medio como una medida clínica, porque las entradas del modelo permanecen constantes.','TW03','flow',[0,1],'deep'),
 ('Compara con propósito','Volvemos a la activación reducida. Identifica el cambio observable antes de añadir otras variables. La exploración permite repetir la comparación y ver cómo intervienen también las conexiones, la salida y la conductancia inversa.','TW04','flow',[0,1],'overview')])
twin('TW05','Apertura y coaptación valvular','Reconoce inserción, borde libre y bloqueo ideal del flujo inverso del modelo.',[
 ('Pared y valvas','La pared se muestra abierta para observar dos valvas. Sus inserciones permanecen unidas a la pared y los bordes libres se aproximan hacia el centro. Las proporciones están ampliadas; el corte es una decisión de visualización.','TW05','valve',[0,0],'section'),
 ('Apertura','Cuando el flujo calculado es positivo, las valvas se abren en esta representación. Sigue la dirección de los trazadores y el cursor de la curva. La apertura ilustra el estado funcional del modelo; no resuelve la mecánica del tejido.','TW05','valve',[0,.25],'detail'),
 ('Coaptación','Al cambiar el gradiente, los bordes se aproximan. En este perfil competente, la formulación bloquea el flujo inverso de la rama. Comprueba la lectura y la curva antes de interpretar una posición de las valvas como una observación clínica.','TW05','valve',[.39,.47],'detail'),
 ('Integra el ciclo','Recuperamos el conjunto y repetimos el ciclo. La relación importante es entre flujo calculado y estado representado. La evaluación clínica de una válvula exige su contexto y un estudio adecuado; no se obtiene de esta geometría ilustrativa.','TW05','valve',[0,1],'overview')])
twin('TW06','Cómo se representa una fuga','Relaciona conductancia inversa, defecto ilustrativo de coaptación y flujo con signo.',[
 ('Una condición diferente','Este perfil permite conductancia inversa en la rama. El defecto de coaptación representa esa condición del modelo. No es una medida de lesión anatómica ni un grado clínico de insuficiencia. Mira cómo se conserva la inserción de las valvas.','TW06','valve',[0,0],'section'),
 ('Durante la eyección','Primero observamos el flujo positivo. La apertura acompaña la onda, igual que en el perfil competente. La diferencia entre ambos perfiles no debe juzgarse únicamente por una imagen de las valvas abiertas.','TW06','valve',[0,.25],'detail'),
 ('Inversión calculada','Durante la fase siguiente aparece flujo negativo. La curva pasa bajo cero y los trazadores invierten el sentido. Esos tres elementos describen el mismo instante. Una inversión del modelo no sustituye la medición clínica de duración y condiciones de provocación.','TW06','valve',[.38,.5],'detail'),
 ('Referencia competente','Compara ahora con la rama competente: bajo estas condiciones el flujo inverso queda bloqueado. Conserva la misma orientación y observa el ciclo completo. En Explorar puedes abrir la comparación simultánea para contrastar ambos resultados.','TW05','valve',[0,1],'overview')])
twin('TW07','La conexión entre sistemas','Sigue el intercambio calculado entre los compartimentos distales.',[
 ('Localiza la conexión','La rama verde conecta los compartimentos distales superficial y profundo. En anatomía, una vena perforante atraviesa la fascia; este circuito simplifica esa relación. El color identifica la conexión y no establece por sí mismo su función clínica.','TW07','flow',[0,0],'superficial'),
 ('Sigue el intercambio','A lo largo del ciclo cambia la diferencia de potencial entre ambos lados. La dirección del trazador y el valor con signo muestran el intercambio calculado. No asumas que una flecha fija describe todas las fases o todas las perforantes.','TW07','flow',[0,1],'deep'),
 ('Confirma en el circuito','El circuito hace explícita esa conexión. Relaciona su valor con las presiones y los volúmenes de los nodos. La comunicación está representada como un elemento de la red, sin reconstruir trayectos fasciales individuales.','TW07','circuit',[0,1],'overview'),
 ('Del esquema a la evaluación','Regresa a la vista espacial y repite el ciclo. Para evaluar una perforante en clínica hacen falta localización, maniobras y dúplex. Su existencia o su diámetro aislados no justifican una interpretación terapéutica.','TW07','flow',[0,1],'overview')])
twin('TW08','Una conexión menos conductora','Distingue conductancia del modelo y diagnóstico anatómico.',[
 ('Menor conductancia','La conexión verde tiene una conductancia menor en este perfil. Su presencia sigue visible porque no estamos eliminando la anatomía. Hemos cambiado una propiedad funcional de la red para observar sus consecuencias.','TW08','flow',[0,0],'superficial'),
 ('Resultado del ciclo','Sigue el intercambio calculado durante la contracción y la relajación. El tamaño aparente de la línea no debe utilizarse como una medición de la vena. La lectura numérica representa flujo relativo dentro de las ecuaciones.','TW08','flow',[0,1],'deep'),
 ('Contraste controlado','Mostramos el perfil con mayor conexión. Escena, lecturas y curva pertenecen ahora a esa solución. Compara las condiciones y la onda, sin atribuir al cambio una mejoría clínica automática.','TW07','flow',[0,1],'superficial'),
 ('Qué permanece','Volvemos a la conexión menos conductora. Los compartimentos y la regla de conservación siguen presentes. En la exploración, cambia una condición y formula una predicción antes de observar el resultado.','TW08','circuit',[0,1],'overview')])
twin('TW09','Resistencia a la salida','Reconoce una condición de frontera sin confundirla con una estenosis reconstruida.',[
 ('Sitúa la salida','El marcador de salida representa mayor resistencia en la red. No dibuja una estenosis anatómica ni mide el porcentaje de obstrucción de una vena. Localiza primero el trayecto al que se aplica esa condición.','TW09','flow',[0,0],'outflow'),
 ('Lee la consecuencia','La presión y la forma de las ondas cambian durante el ciclo. El modelo estabiliza sus volúmenes antes de mostrar la solución. Mira la curva correspondiente y evita deducir una presión de paciente a partir de sus unidades relativas.','TW09','flow',[0,1],'deep'),
 ('Comprueba los nodos','En el circuito, cada salida y conexión puede seguirse sin ocultamientos. La conservación permite comprobar el balance de la red. Una mayor resistencia no se traduce automáticamente en un diagnóstico o una indicación de intervención.','TW09','circuit',[0,1],'overview'),
 ('Añade una pregunta','Regresamos al conjunto: ¿qué podría cambiar si existiera una vía adicional? El experimento de colaterales permite explorar esa pregunta con otra solución, manteniendo explícitas las condiciones que se comparan.','TW09','flow',[0,1],'overview')])
twin('TW10','Una vía colateral en la red','Identifica una rama adicional y su flujo propio calculado.',[
 ('Una ruta adicional','La rama ocre añade una vía colateral al perfil con resistencia de salida. Su trazado es esquemático. La presencia de una colateral en una imagen clínica exige interpretación anatómica y funcional, no una conclusión automática sobre la gravedad.','TW10','flow',[0,0],'overview'),
 ('Distribución del flujo','Sigue el flujo de esa rama durante el ciclo. Tiene su propio valor calculado; no es una animación decorativa. Relaciónalo con las lecturas de las otras ramas y con la presión de la red.','TW10','flow',[0,1],'outflow'),
 ('Sin esa rama','Mostramos el perfil de resistencia sin la vía adicional. La comparación pregunta cómo se redistribuye el flujo cuando cambia la conectividad. No representa la oclusión o apertura de una colateral en tiempo real dentro de un paciente.','TW09','flow',[0,1],'outflow'),
 ('Contrasta ambas redes','Volvemos a la red con colateral y la expresamos como circuito. Comprueba qué conexión se añadió y cómo se conserva el balance. La exploración permite revisar ambas soluciones con un mismo período.','TW10','circuit',[0,1],'overview')])
twin('TW11','Presión exterior y volumen','Relaciona presión transmural y respuesta del compartimento superficial.',[
 ('Soporte externo','Este perfil modifica la presión exterior del compartimento superficial. La representación señala el lugar de aplicación. El control es una condición docente sin calibración clínica y no prescribe una presión de compresión.','TW11','flow',[0,0],'superficial'),
 ('Mira el volumen','Al cambiar la diferencia entre presión interna y externa, cambia el volumen calculado. La curva muestra el mismo compartimento que la escena. El calibre se utiliza para representar volumen a longitud fija, no como una medición ecográfica.','TW11','flow',[0,1],'superficial'),
 ('Presión no es receta','El circuito permite separar presión, volumen y flujo. El soporte externo forma parte del contexto mecánico, pero la selección clínica de compresión requiere valoración y guías. Este modelo no calcula tallas, dosis de presión ni seguridad arterial.','TW11','circuit',[0,1],'overview'),
 ('Explora una relación','Recupera la red y observa otra vez el ciclo. Antes de mover el ajuste, predice la dirección del cambio de volumen. Contrasta luego tu predicción con la curva, manteniendo las demás condiciones.','TW11','flow',[0,1],'overview')])
twin('TW12','Mecanismos que interactúan','Integra bomba, válvulas, conexiones y presión exterior sin inferir efectos terapéuticos.',[
 ('Reconoce las condiciones','Aquí intervienen varias condiciones a la vez: bomba, conductancia inversa, conexión, salida y presión exterior. Identifica sus valores antes de interpretar la escena. Una combinación visualmente compleja no equivale a una simulación individual más validada.','TW12','flow',[0,0],'overview'),
 ('Observa un ciclo','Sigue la activación y el transporte en las ramas. Sus flujos pueden cambiar de forma diferente porque dependen de la red completa. La lectura temporal resulta más informativa que una imagen aislada de las partículas.','TW12','flow',[0,1],'deep'),
 ('Verifica el circuito','El circuito revela qué compartimentos reciben y entregan flujo. Compara presiones y volúmenes mientras avanza el cursor. Los resultados son relativos y las entradas constantes limitan lo que puede inferirse del retorno medio.','TW12','circuit',[0,1],'overview'),
 ('Descompón el problema','Vuelve a la red. Para comprender una interacción, empieza comparando perfiles simples y añade condiciones de una en una. Esta herramienta permite ensayar explicaciones causales, sin predecir la respuesta de una persona a un tratamiento.','TW12','flow',[0,1],'overview')])

dp={l['id']:l for l in json.loads((root/'src/data/educational-content.json').read_text(encoding='utf-8'))['dopplerLessons']}
def doppler(id,objective,parts):
    d=dp[id]
    lesson(id,'doppler',d['title'],objective,d['sourceIds'],[stage(t,s,values=v,shot='overview',phase=([[0,.2],[.2,.6],[.6,.6],[.6,1]][i] if id=='DP09' else [0,1])) for i,(t,s,v) in enumerate(parts)],f'/flebodus?tab=doppler&lesson={id}')
doppler('DP01','Relaciona el haz con la componente del movimiento que detecta.',[
 ('Dos direcciones','El transductor y el flujo tienen direcciones diferentes. La flecha del vaso representa movimiento y el haz señala la dirección de observación. El esquema separa ambos para explicar qué componente participa en el desplazamiento Doppler.',{'angle':25,'velocity':20}),
 ('La proyección','Al cambiar el ángulo, cambia la proyección del movimiento sobre el haz. La curva sintética representa esa componente, no la velocidad total del vaso. Un ángulo cercano a perpendicular reduce la componente detectada en esta idealización.',{'angle':80,'velocity':20}),
 ('Cambia el sentido relativo','Al sobrepasar la perpendicular cambia el signo de la proyección. Eso describe la relación con el haz y la convención de presentación. No identifica automáticamente arteria, vena, normalidad o enfermedad.',{'angle':135,'velocity':20}),
 ('Pregunta antes de interpretar','Regresamos a la orientación inicial. Antes de interpretar un signo, localiza el transductor, la dirección del flujo y la configuración del equipo. En clínica se necesitan anatomía y protocolo, además de la señal.',{'angle':25,'velocity':20})])
doppler('DP02','Distingue el mapa de presentación de la dirección física del movimiento.',[
 ('Reconoce el mapa','El color Doppler representa información de movimiento según un mapa y una referencia. El rojo y el azul de esta demostración no identifican por sí mismos arterias o venas. Localiza la leyenda antes de interpretar.',{'invert':0,'velocity':25}),
 ('Invierte la presentación','Ahora invertimos el mapa manteniendo la misma señal ilustrativa. Cambia el color mostrado, pero no hemos invertido el flujo. Esta separación es esencial cuando una imagen se interpreta sin conocer sus ajustes.',{'invert':1,'velocity':25}),
 ('Movimiento en otro sentido','Cambiamos el sentido de la señal y conservamos el mapa invertido. Relaciona ambas decisiones con la leyenda. Un color aislado no permite nombrar el vaso ni confirmar reflujo.',{'invert':1,'velocity':-25}),
 ('Conserva el contexto','Volvemos al mapa inicial. En la práctica, orientación del haz, escala, inversión y adquisición forman parte de la lectura. Describe el movimiento en su contexto anatómico y evita utilizar el color como diagnóstico independiente.',{'invert':0,'velocity':25})])
doppler('DP03','Encuentra la referencia cero antes de leer una onda.',[
 ('Una referencia común','La línea base indica la referencia cero del registro. El trazo sintético se muestra sobre una cuadrícula temporal. Antes de comparar signos o amplitudes, identifica el cero y las unidades de presentación.',{'baseline':0,'scale':50}),
 ('Desplaza la línea base','Ahora cambia la posición de esa referencia en pantalla. La demostración desplaza el conjunto de la presentación; no añade una nueva alteración fisiológica. Sigue la onda respecto del cero, no respecto del borde del visor.',{'baseline':30,'scale':50}),
 ('Otra posición','Situamos la línea base en el otro sentido. La lectura debe seguir utilizando la referencia visible. La forma de una captura y su encuadre pueden modificar la impresión que produce una misma señal.',{'baseline':-25,'scale':50}),
 ('Interpretación completa','Regresamos al centro. En un registro clínico, conserva metadatos, escala y referencia antes de comparar con otro estudio. Esta curva es sintética y no representa una medición de un paciente.',{'baseline':0,'scale':50})])
doppler('DP04','Diferencia escala del visor y cambio de la señal.',[
 ('La misma señal','La curva parte de una velocidad ilustrativa constante en sus condiciones de base. Su tamaño en pantalla depende de la escala vertical. El propósito es separar la magnitud representada de su apariencia.',{'scale':40,'velocity':20}),
 ('Amplía la escala','Al ampliar el rango vertical, la misma onda ocupa menos altura. La sangre no ha cambiado de velocidad por este ajuste. La comparación visual exige leer los valores y sus unidades.',{'scale':90,'velocity':20}),
 ('Acerca el rango','Con un rango menor, el trazo ocupa más espacio y puede salir del área visible. Este recorte gráfico no debe confundirse con aliasing, cuyo mecanismo depende del muestreo pulsado.',{'scale':20,'velocity':20}),
 ('Compara con referencia','Volvemos al rango inicial. Distingue un cambio de configuración de un cambio físico de la señal. Conserva la escala cuando presentes dos registros y comprueba si sus condiciones de adquisición son comparables.',{'scale':40,'velocity':20})])
doppler('DP05','Comprende la dependencia angular de la ecuación Doppler ideal.',[
 ('Ángulo y proyección','La ecuación Doppler incluye el coseno del ángulo entre haz y movimiento. El esquema muestra esa relación geométrica y una señal ilustrativa. No es una medición cuantitativa de un vaso adquirido.',{'angle':30,'frequency':5,'velocity':20}),
 ('Hacia la perpendicular','Al aproximar el haz a la perpendicular, disminuye la componente proyectada. Esa dependencia también aumenta la sensibilidad de una estimación a errores de orientación. La corrección angular requiere definir adecuadamente el eje del flujo.',{'angle':85,'frequency':5,'velocity':20}),
 ('Frecuencia de emisión','Cambiamos la frecuencia de emisión en la ecuación ideal y mantenemos la velocidad. Varía el desplazamiento Doppler, no la velocidad física impuesta. Frecuencia, ángulo y velocidad tienen papeles distintos.',{'angle':45,'frequency':8,'velocity':20}),
 ('Lee la adquisición','Recuperamos las condiciones iniciales. Antes de usar una cifra clínica, revisa orientación, volumen de muestra y ajustes pertinentes. Esta demostración explica una relación matemática, no certifica la calibración de un equipo.',{'angle':30,'frequency':5,'velocity':20})])
doppler('DP06','Reconoce el límite de Nyquist y el plegamiento de una señal pulsada.',[
 ('Señal y muestreo','El Doppler pulsado representa una señal dentro de un intervalo determinado por la frecuencia de repetición de pulsos. Las líneas señalan el límite de Nyquist. Distinguimos la señal impuesta de la que puede mostrarse dentro de ese intervalo.',{'prf':2000,'shift':800}),
 ('Aparece el plegamiento','Reducimos la frecuencia de repetición manteniendo el desplazamiento original. La señal supera el límite y se representa plegada al otro lado. Ese signo mostrado no demuestra por sí mismo una inversión física del flujo.',{'prf':1000,'shift':800}),
 ('Recupera el intervalo','Al aumentar de nuevo el rango de muestreo, la misma señal puede representarse sin ese plegamiento. En una adquisición real existen restricciones relacionadas con profundidad y configuración; no todo ajuste puede modificarse libremente.',{'prf':3000,'shift':800}),
 ('Distingue los fenómenos','Compara la señal original, el límite y el valor representado. Aliasing, inversión del mapa y cambio verdadero de dirección son fenómenos diferentes. Este ejemplo usa valores sintéticos para hacer visible esa distinción.',{'prf':1000,'shift':800})])
doppler('DP07','Relaciona una señal temporal con el evento que la provoca.',[
 ('Sitúa el evento','Una onda temporal necesita una referencia del evento que la acompaña. El marcador señala una maniobra ilustrativa y el área destaca el intervalo que queremos observar. El tiempo se lee en el eje horizontal.',{'eventTime':2,'duration':.8}),
 ('El momento importa','Desplazamos el evento y conservamos la duración del intervalo. No hemos creado una nueva velocidad de la sangre; estamos mostrando cómo cambia la relación temporal dentro del registro docente.',{'eventTime':3.5,'duration':.8}),
 ('Delimita el intervalo','Ahora cambia la duración representada. El inicio y el final deben colocarse según el fenómeno y su adquisición, no por la anchura aparente de una captura. Esta demostración no asigna una clase clínica.',{'eventTime':2,'duration':1.2}),
 ('Documenta condiciones','Recuperamos la referencia inicial. Un informe útil relaciona señal, segmento, postura y maniobra. La interpretación de reflujo requiere el protocolo y el territorio correspondientes, además de medir correctamente el tiempo.',{'eventTime':2,'duration':.8})])
doppler('DP08','Distingue variación temporal de una conclusión diagnóstica.',[
 ('Una onda modulada','La señal sintética varía a lo largo del tiempo. Su modulación permite explicar el concepto de fasicidad. El esquema no reproduce el registro respiratorio o cardíaco de una persona.',{'modulation':60,'period':4}),
 ('Modulación menor','Reducimos la amplitud de la modulación mientras mantenemos el período del ejemplo. La onda se vuelve menos variable. Ese aspecto aislado no basta para localizar una lesión o excluir enfermedad.',{'modulation':15,'period':4}),
 ('Otra periodicidad','Cambiamos el período del esquema. Frecuencia de repetición y amplitud son propiedades diferentes de la variación temporal. En clínica deben interpretarse con la adquisición y otras observaciones.',{'modulation':60,'period':2.5}),
 ('Integra la información','Volvemos a la onda inicial. Describe qué observas, compara condiciones y evita convertir un patrón único en diagnóstico. La información temporal es una pieza del estudio, junto a anatomía, compresibilidad y otras señales.',{'modulation':60,'period':4})])
doppler('DP09','Distingue un renderizado experimental de una serie cuantitativa importada.',[
 ('Procedencia visible','Este material procede del conjunto experimental Waterloo, distribuido por sus autores. Muestra un renderizado publicado del flujo femoral. Su naturaleza es diferente de las curvas sintéticas de las otras lecciones.',{'phase':0}),
 ('Observa el movimiento','La secuencia permite observar cambios espaciales y temporales en el renderizado. Conserva sus leyendas y condiciones. La visualización de vectores no convierte automáticamente un archivo de video en datos numéricos accesibles.',{'phase':35}),
 ('Límite de medición','En esta aplicación no se importaron las matrices de radiofrecuencia ni una serie cuantitativa de velocidades. No extraigas cifras físicas desde el color del video o desde el tamaño aparente de una flecha.',{'phase':65}),
 ('Relaciona las fuentes','Revisa el protocolo y la publicación del recurso para conocer su origen. Esta pieza acompaña la explicación de flujo y adquisición; no sustituye un estudio clínico, una calibración regional ni una validación diagnóstica.',{'phase':90})])
doppler('DP10','Mide un intervalo de inversión y conserva territorio y maniobra.',[
 ('Define qué mides','La curva muestra una inversión sintética respecto de la referencia cero. Los dos marcadores delimitan un intervalo. Esa duración es distinta de la amplitud de la onda y exige situar correctamente inicio y final.',{'duration':.35,'deep':0}),
 ('Compara intervalos','Al ampliar la duración, el área negativa ocupa más tiempo. La representación ayuda a practicar lectura temporal, sin diagnosticar un paciente. La provocación y el segmento evaluado siguen siendo parte esencial de la interpretación.',{'duration':.8,'deep':0}),
 ('El territorio cambia el contexto','No debe aplicarse un único umbral a todos los segmentos profundos. Las guías distinguen territorios y condiciones; consulta la referencia completa antes de clasificar un hallazgo. Esta vista resalta esa necesidad de contexto.',{'duration':1.2,'deep':1}),
 ('Conserva el protocolo','Describe duración, segmento y maniobra junto a las limitaciones de adquisición. El color aislado y una imagen fija no completan el estudio de reflujo. Usa el laboratorio para practicar el intervalo y revisa las fuentes del protocolo.',{'duration':.8,'deep':0})])

clinical=[
 ('C0','Sin signos visibles o palpables','Distingue ausencia de signos de ausencia de síntomas.',[
  ('Qué significa cero','La clase cero describe ausencia de signos venosos visibles o palpables. No significa que la persona no tenga síntomas. Una fotografía solo contiene parte de esa evaluación y no permite comprobar la palpación.'),
  ('Describe el recurso','Estos ejemplos conservan la etiqueta del depósito original. Puedes describir lo visible, la distribución y las limitaciones de la imagen. La etiqueta no equivale a una adjudicación independiente por miembro realizada por esta aplicación.'),
  ('Completa el contexto','La historia de síntomas y la exploración aportan información que no está en los píxeles. Los dominios de etiología, anatomía y fisiopatología tampoco se asignan automáticamente a partir de una imagen sin signos visibles.'),
  ('Comprueba el concepto','Antes de escribir asintomático, pregunta por los síntomas atribuibles al trastorno venoso. La clasificación describe un caso evaluado; no es una escala de gravedad ni una secuencia obligatoria que comience en estas fotografías.')]),
 ('C1','Telangiectasias o venas reticulares','Describe el patrón superficial y distingue C1 de corona flebectásica.',[
  ('Una definición disyuntiva','La clase uno incluye telangiectasias o venas reticulares. No exige que estén presentes ambas. Observa la distribución superficial y conserva una descripción del patrón antes de atribuirle un mecanismo funcional.'),
  ('Observación con límites','Las imágenes mantienen sus etiquetas de origen. Sin una escala validada no puedes medir el diámetro real desde la pantalla. Tampoco puedes reconstruir desde el aspecto superficial todo el circuito de reflujo.'),
  ('El contexto del tobillo','La corona flebectásica tiene un patrón y una localización característicos y se incluye como subclase cuatro ce en la revisión de dos mil veinte. No equivale a cualquier telangiectasia aislada.'),
  ('Describe y pregunta','Compara los ejemplos y formula qué información clínica falta. Una descripción precisa distingue el hallazgo visible de sus causas y síntomas. La fotografía apoya la enseñanza, pero no completa los cuatro dominios de la clasificación.')]),
 ('C2','Várices y recurrencia','Distingue el hallazgo clínico de su etiología y de la recurrencia.',[
  ('Sigue los trayectos','La clase dos corresponde a várices. Sigue la distribución de los trayectos superficiales visibles en estos ejemplos. Las fotografías son material del depósito y conservan su clasificación de origen.'),
  ('Más allá del aspecto','El aspecto de una vena no describe por sí solo síntomas, etiología o el origen de un reflujo. La exploración y el dúplex permiten completar preguntas que la imagen superficial deja abiertas.'),
  ('Cuándo hablar de recurrencia','El modificador de recurrencia requiere antecedentes clínicos documentados. No se deduce del número de vasos visibles ni de su color. La aplicación no añade ese modificador automáticamente a las fotografías.'),
  ('Una observación útil','Compara distribución y condiciones de captura. Después distingue lo observado de lo que preguntarías o estudiarías. La clase clínica es parte de una descripción más amplia, no un diagnóstico funcional completo.')]),
 ('C3','Edema y contexto clínico','Reconoce por qué el edema requiere exploración y evaluación de causa.',[
  ('La clase del depósito','La clase tres describe edema en el contexto de la clasificación venosa. Estos ejemplos conservan esa etiqueta. El contorno en una fotografía no permite confirmar por sí solo edema ni demostrar su causa.'),
  ('Observa sin concluir de más','Describe simetría, distribución y lo que queda fuera del encuadre. La presencia de aumento de volumen puede requerir historia, exploración y estudio de otras causas; no todos los miembros hinchados tienen la misma etiología.'),
  ('Exploración necesaria','La evaluación directa permite comprobar hallazgos y relacionarlos con su evolución. Los datos venosos se interpretan junto al resto del contexto. La imagen no contiene esa entrevista ni sustituye una exploración física.'),
  ('Una pregunta clínica','Antes de atribuir el edema a enfermedad venosa, identifica qué información falta. La tarea educativa es formular una descripción y una necesidad de evaluación; no asignar una causa automática desde el aspecto de la fotografía.')]),
 ('C4','Cambios cutáneos: las tres subclases','Distingue C4a, C4b y C4c conservando los límites de las fotos generales C4.',[
  ('Cambios con contexto','La clase cuatro reúne cambios cutáneos o subcutáneos secundarios a enfermedad venosa crónica. El banco conserva etiquetas generales de clase cuatro. Sus fotos no están reclasificadas como una subclase por esta aplicación.'),
  ('Pigmentación y eccema','La subclase cuatro a incluye pigmentación o eccema. Describe localización, superficie y color, y conserva el contexto causal. El aspecto por sí solo no reemplaza la valoración que atribuye el cambio a enfermedad venosa.'),
  ('Induración y atrofia blanca','La subclase cuatro be incluye lipodermatosclerosis o atrofia blanca. Parte de la evaluación requiere exploración, como la induración. Una fotografía general del depósito no documenta automáticamente todos los criterios de esa subclase.'),
  ('Corona flebectásica','La revisión de dos mil veinte incorpora la corona flebectásica como cuatro ce. Es un patrón de pequeñas venas en abanico en tobillo y pie, distinto de una telangiectasia aislada. Conserva estas distinciones sin adjudicarlas automáticamente a los ejemplos.')]),
 ('C5','Úlcera venosa cicatrizada','Relaciona una cicatriz con los antecedentes necesarios para describir C5.',[
  ('Una historia que importa','La clase cinco corresponde a úlcera venosa cicatrizada. Una cicatriz visible no demuestra por sí sola que existió una úlcera venosa. Hace falta conocer el antecedente y la atribución de su causa.'),
  ('Describe el área','Observa localización, superficie y cambios alrededor del área cicatricial. Estos ejemplos mantienen la etiqueta original del depósito. Las diferencias de iluminación y captura limitan las comparaciones de color y textura.'),
  ('Cicatrizada no es sin enfermedad','La ausencia de una herida abierta en el momento de la imagen no elimina la necesidad de evaluación venosa. La clasificación describe manifestaciones presentes y antecedentes pertinentes, sin garantizar un pronóstico individual.'),
  ('Completa la descripción','Distingue el hallazgo visible de la historia que lo sustenta. La fotografía no permite completar por sí sola etiología, anatomía, fisiopatología o síntomas. Formula las preguntas antes de cerrar la clasificación de un miembro.')]),
 ('C6','Úlcera activa y recurrencia','Distingue herida visible, atribución venosa y antecedentes de recurrencia.',[
  ('La herida y su causa','La clase seis corresponde a úlcera venosa activa. La pérdida de continuidad de la piel puede verse en una imagen, pero su causa venosa exige evaluación. No toda herida del tobillo tiene la misma etiología.'),
  ('Describe lo observable','Observa distribución y características visibles sin deducir la causa desde el color. Las fotografías conservan sus etiquetas de origen y no incluyen una valoración clínica completa ni un plan de tratamiento.'),
  ('Recurrencia documentada','El modificador de recurrencia requiere antecedentes. No puede inferirse automáticamente por el tamaño o aspecto de la herida. La revisión de dos mil veinte distingue esa información del hallazgo de una úlcera activa.'),
  ('Integra el caso','La descripción clínica se completa con historia, exploración y los estudios correspondientes. Los ejemplos sirven para aprender a observar y preguntar. No permiten indicar un tratamiento ni predecir cicatrización desde la pantalla.')])]
for cls,title,obj,parts in clinical:
    lesson('CEAP-'+cls,'vision',title,obj,['ceap2020','esvs2022','tricvi'],[stage(t,s,clinicalClass=cls,subclass=(None if i==0 else 'C4a' if i==1 else 'C4b' if i==2 else 'C4c') if cls=='C4' else None,example=i%2,phase=[0,1],shot='overview') for i,(t,s) in enumerate(parts)],f'/flebovision?class={cls}')

lesson('AN01','anatomy','Anatomía por planos','Localiza huesos, músculos y venas sin confundir referencia anatómica con el modelo funcional.',['uipnomenclature','uipduplex2','bodyparts3d'],[
 stage('Referencias óseas','El modelo procede de BodyParts tres de y representa una selección de estructuras del miembro inferior izquierdo. Comenzamos con los huesos para situar el eje y reconocer el contexto espacial antes de añadir otras capas.',tissues=['bone'],view='anatomy',scenario='TW03',phase=[0,0],shot='overview'),
 stage('Plano muscular','Añadimos músculos de la pantorrilla. Su relación con las venas es importante para comprender la bomba muscular. Esta referencia anatómica no se deforma ni calcula la contracción de un paciente; ese mecanismo se explica en el esquema funcional.',tissues=['bone','muscle'],view='anatomy',scenario='TW03',phase=[0,0],shot='section'),
 stage('Territorios venosos','Las venas se incorporan al contexto. Reconoce superficial, profundo y sus relaciones, teniendo presente que la selección no incluye todas las ramas ni las variantes. La nomenclatura se consulta en las fuentes flebológicas.',tissues=['bone','muscle','vein'],view='anatomy',scenario='TW03',phase=[0,0],shot='overview'),
 stage('Vuelve al conjunto','Aislamos visualmente las venas conservando el encuadre. Puedes girar y recuperar los planos para comprender las relaciones. La referencia anatómica y el modelo hemodinámico cumplen funciones diferentes; sus formas no constituyen una calibración individual.',tissues=['vein'],view='anatomy',scenario='TW03',phase=[0,0],shot='detail')],'/flebotwin?view=anatomy')
lesson('DC01','cine','Observar una compresión real','Relaciona cuadros, maniobra, etiqueta de origen y alcance del estudio.',['uipduplex1','aium2026','esvsthrombosis2021','thrombus'],[
 stage('Una adquisición real','Este cine de compresión procede del conjunto público ThrombUS. Conservamos sus cuadros, dimensiones y tiempo de adquisición. La etiqueta del proveedor describe ese recurso; no equivale a una revisión diagnóstica independiente realizada por la aplicación.',clipId='dus-cfv-001',phase=[0,.15],shot='overview'),
 stage('Sigue la maniobra','Observa la respuesta de la estructura durante la compresión con el transductor. El segmento y el lado documentados ayudan a situar el recurso. La postura y la orientación no deben inventarse cuando el depósito no las informa.',clipId='dus-cfv-001',phase=[.15,.65],shot='overview'),
 stage('Pausa con propósito','Detenemos un cuadro para describir lo visible. Una sola imagen no representa toda la maniobra ni un protocolo completo. El avance por cuadros permite volver a examinar la secuencia sin crear imágenes intermedias sintéticas.',clipId='dus-cfv-001',phase=[.65,.65],shot='overview'),
 stage('Alcance y registro','Revisamos el final del extracto. El estudio clínico integra anatomía, compresibilidad y otros hallazgos según el protocolo. Aquí el tiempo está documentado; las distancias y velocidades permanecen limitadas por la calibración espacial disponible.',clipId='dus-cfv-001',phase=[.65,1],shot='overview')],'/flebodus?case=dus-cfv-001')

