def esc(s): return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
jobs=[dict(id=l['id'],voiceId='84854979e66846989bc6c5855f53268f',language='es',inputType='ssml',text='<speak>'+ '<break time="0.9s"/>'.join(esc(s['spoken']) for s in l['stages'])+'</speak>',stages=[s['spoken'] for s in l['stages']]) for l in lessons]
